INSERT INTO products (product_group_id, handle, title, description, description_html, vendor, product_type, created_at, currency_code, position) VALUES
('gid://catalog/Product/9000', 'essential-cotton-tee', 'Essential Cotton Tee - White', 'A camiseta que resolve qualquer dia. Malha 100% algodão penteado de 180g, com caimento reto que não marca o corpo e gola canelada que não cede na lavagem. Serve sozinha no calor ou por baixo de moletom e jaqueta quando esfria.', '<p>A camiseta que resolve qualquer dia. Malha 100% algodão penteado de 180g, com caimento reto que não marca o corpo e gola canelada que não cede na lavagem. Serve sozinha no calor ou por baixo de moletom e jaqueta quando esfria.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 100),
('gid://catalog/Product/9001', 'heavyweight-boxy-tee', 'Heavyweight Boxy Tee - Black', 'Algodão pesado de 240g com modelagem boxy: ombro caído, corpo largo e barra na altura do quadril. O tecido encorpado faz a peça cair estruturada em vez de grudar, o que sustenta o visual oversized sem parecer um tamanho maior por acidente.', '<p>Algodão pesado de 240g com modelagem boxy: ombro caído, corpo largo e barra na altura do quadril. O tecido encorpado faz a peça cair estruturada em vez de grudar, o que sustenta o visual oversized sem parecer um tamanho maior por acidente.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 101),
('gid://catalog/Product/9002', 'studio-pocket-tee', 'Studio Pocket Tee - Sage', 'Camiseta de bolso em algodão macio, com costura reforçada no ombro. O bolso é chapado e discreto, do tamanho certo para não deformar o caimento. Uma peça neutra para quem prefere que a roupa não grite.', '<p>Camiseta de bolso em algodão macio, com costura reforçada no ombro. O bolso é chapado e discreto, do tamanho certo para não deformar o caimento. Uma peça neutra para quem prefere que a roupa não grite.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 102),
('gid://catalog/Product/9003', 'night-shift-graphic-tee', 'Night Shift Graphic Tee - Black', 'Estampa serigrafada em tinta à base d''água, que penetra na malha em vez de formar película — não craquela nem esquenta. Base de algodão preto com lavagem enzimática, então já chega com aquele toque macio de camiseta velha favorita.', '<p>Estampa serigrafada em tinta à base d''água, que penetra na malha em vez de formar película — não craquela nem esquenta. Base de algodão preto com lavagem enzimática, então já chega com aquele toque macio de camiseta velha favorita.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 103),
('gid://catalog/Product/9004', 'capybara-club-tee', 'Capybara Club Tee - White', 'Ilustração de capivara no peito, desenhada à mão e impressa em tom sobre tom. Algodão leve de 160g, ideal para dias quentes. É a peça que gera conversa sem precisar de logo grande.', '<p>Ilustração de capivara no peito, desenhada à mão e impressa em tom sobre tom. Algodão leve de 160g, ideal para dias quentes. É a peça que gera conversa sem precisar de logo grande.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 104),
('gid://catalog/Product/9005', 'long-sleeve-daily-tee', 'Long Sleeve Daily Tee - Black', 'Manga longa em algodão de gramatura média, com punho canelado que segura no lugar. Funciona como camiseta em meia-estação e como segunda pele por baixo de casaco no frio.', '<p>Manga longa em algodão de gramatura média, com punho canelado que segura no lugar. Funciona como camiseta em meia-estação e como segunda pele por baixo de casaco no frio.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 105),
('gid://catalog/Product/9006', 'vintage-wash-tee', 'Vintage Wash Tee - Black', 'Lavagem estonada feita peça a peça, então nenhuma sai idêntica à outra. O algodão perde rigidez no processo e ganha um caimento fluido que normalmente só aparece depois de um ano de uso.', '<p>Lavagem estonada feita peça a peça, então nenhuma sai idêntica à outra. O algodão perde rigidez no processo e ganha um caimento fluido que normalmente só aparece depois de um ano de uso.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 106),
('gid://catalog/Product/9007', 'relaxed-crop-tee', 'Relaxed Crop Tee - White', 'Comprimento cropped que para na cintura alta, com corpo folgado para não marcar. Algodão leve com leve elastano na gola, que evita o alargamento típico de camiseta cortada.', '<p>Comprimento cropped que para na cintura alta, com corpo folgado para não marcar. Algodão leve com leve elastano na gola, que evita o alargamento típico de camiseta cortada.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 107),
('gid://catalog/Product/9008', 'kids-capybara-tee', 'Kids Capybara Tee - Cream', 'Camiseta infantil com duas capivaras amigas estampadas na frente. Algodão macio sem etiqueta interna — costurada com etiqueta impressa, porque criança não perdoa raspagem no pescoço.', '<p>Camiseta infantil com duas capivaras amigas estampadas na frente. Algodão macio sem etiqueta interna — costurada com etiqueta impressa, porque criança não perdoa raspagem no pescoço.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 108),
('gid://catalog/Product/9009', 'kids-everyday-tee', 'Kids Everyday Tee - Black', 'A camiseta de todo dia para criança: algodão resistente que aguenta lavagem frequente, com costura dupla na gola e nas cavas, onde a roupa infantil costuma ceder primeiro.', '<p>A camiseta de todo dia para criança: algodão resistente que aguenta lavagem frequente, com costura dupla na gola e nas cavas, onde a roupa infantil costuma ceder primeiro.</p>', 'Deco Store', 'T-Shirt', '2026-08-05T00:00:00Z', 'BRL', 109),
('gid://catalog/Product/9010', 'classic-pullover-hoodie', 'Classic Pullover Hoodie - Grey', 'Moletom fechado com capuz forrado e cordão em algodão encerado. Felpa interna escovada que segura o calor sem peso, e bolso canguru fundo o bastante para as duas mãos e o celular.', '<p>Moletom fechado com capuz forrado e cordão em algodão encerado. Felpa interna escovada que segura o calor sem peso, e bolso canguru fundo o bastante para as duas mãos e o celular.</p>', 'Deco Store', 'Hoodie', '2026-08-05T00:00:00Z', 'BRL', 110),
('gid://catalog/Product/9011', 'oversized-hoodie', 'Oversized Hoodie - White', 'Modelagem propositalmente ampla: ombro caído e manga longa que sobra na mão. O capuz é duplo, então fica em pé mesmo abaixado — detalhe que muda completamente a silhueta.', '<p>Modelagem propositalmente ampla: ombro caído e manga longa que sobra na mão. O capuz é duplo, então fica em pé mesmo abaixado — detalhe que muda completamente a silhueta.</p>', 'Deco Store', 'Hoodie', '2026-08-05T00:00:00Z', 'BRL', 111),
('gid://catalog/Product/9012', 'zip-through-hoodie', 'Zip-Through Hoodie - Blue', 'Moletom com zíper inteiro e puxador metálico. Mais versátil que o fechado: abre quando o dia esquenta e vira camada intermediária por baixo de jaqueta no frio de verdade.', '<p>Moletom com zíper inteiro e puxador metálico. Mais versátil que o fechado: abre quando o dia esquenta e vira camada intermediária por baixo de jaqueta no frio de verdade.</p>', 'Deco Store', 'Hoodie', '2026-08-05T00:00:00Z', 'BRL', 112),
('gid://catalog/Product/9013', 'crewneck-sweatshirt', 'Crewneck Sweatshirt - White', 'Moletom careca de gola canelada, sem capuz e sem bolso. Corte limpo que funciona por cima de camisa social tanto quanto por cima de camiseta — é a peça mais versátil do armário de inverno.', '<p>Moletom careca de gola canelada, sem capuz e sem bolso. Corte limpo que funciona por cima de camisa social tanto quanto por cima de camiseta — é a peça mais versátil do armário de inverno.</p>', 'Deco Store', 'Sweatshirt', '2026-08-05T00:00:00Z', 'BRL', 113),
('gid://catalog/Product/9014', 'boxy-cropped-sweatshirt', 'Boxy Cropped Sweatshirt - Pastel', 'Moletom curto de corpo largo, com barra canelada que assenta acima da cintura. Pensado para usar com calça de cintura alta, deixando aparecer um vão proposital.', '<p>Moletom curto de corpo largo, com barra canelada que assenta acima da cintura. Pensado para usar com calça de cintura alta, deixando aparecer um vão proposital.</p>', 'Deco Store', 'Sweatshirt', '2026-08-05T00:00:00Z', 'BRL', 114),
('gid://catalog/Product/9015', 'heavy-fleece-hoodie', 'Heavy Fleece Hoodie - Grey', 'Felpa pesada de 420g com interior escovado duas vezes. É o moletom para frio de verdade — grosso o bastante para dispensar casaco em dia seco, mas ainda flexível no ombro.', '<p>Felpa pesada de 420g com interior escovado duas vezes. É o moletom para frio de verdade — grosso o bastante para dispensar casaco em dia seco, mas ainda flexível no ombro.</p>', 'Deco Store', 'Hoodie', '2026-08-05T00:00:00Z', 'BRL', 115),
('gid://catalog/Product/9016', 'kids-hoodie', 'Kids Hoodie - Cream', 'Moletom infantil com capuz sem cordão, por segurança. Punhos e barra canelados que seguram no lugar durante a brincadeira, e felpa macia que não coça.', '<p>Moletom infantil com capuz sem cordão, por segurança. Punhos e barra canelados que seguram no lugar durante a brincadeira, e felpa macia que não coça.</p>', 'Deco Store', 'Hoodie', '2026-08-05T00:00:00Z', 'BRL', 116),
('gid://catalog/Product/9017', 'chambray-work-shirt', 'Chambray Work Shirt - Blue', 'Camisa de chambray, o primo leve do jeans: mesma aparência, metade do peso. Botões de madrepérola e bolso no peito. Abre por cima de camiseta como sobrecamisa ou fecha sozinha.', '<p>Camisa de chambray, o primo leve do jeans: mesma aparência, metade do peso. Botões de madrepérola e bolso no peito. Abre por cima de camiseta como sobrecamisa ou fecha sozinha.</p>', 'Deco Store', 'Shirt', '2026-08-05T00:00:00Z', 'BRL', 117),
('gid://catalog/Product/9018', 'linen-blend-shirt', 'Linen Blend Shirt - Multicolor', 'Mistura de linho e algodão que respira como linho puro mas amassa bem menos. Caimento solto e manga que dobra no antebraço — a camisa de calor sem parecer desleixada.', '<p>Mistura de linho e algodão que respira como linho puro mas amassa bem menos. Caimento solto e manga que dobra no antebraço — a camisa de calor sem parecer desleixada.</p>', 'Deco Store', 'Shirt', '2026-08-05T00:00:00Z', 'BRL', 118),
('gid://catalog/Product/9019', 'oxford-button-down', 'Oxford Button-Down - White', 'Oxford de algodão com colarinho abotoado, tecido encorpado que dá estrutura ao colarinho sem engomar. A camisa que vai de reunião a bar sem trocar de peça.', '<p>Oxford de algodão com colarinho abotoado, tecido encorpado que dá estrutura ao colarinho sem engomar. A camisa que vai de reunião a bar sem trocar de peça.</p>', 'Deco Store', 'Shirt', '2026-08-05T00:00:00Z', 'BRL', 119),
('gid://catalog/Product/9020', 'silk-touch-blouse', 'Silk Touch Blouse - Off White', 'Blusa de viscose com toque de seda e caimento fluido. Sem transparência sob luz direta — testada, porque é onde a maioria das blusas claras falha.', '<p>Blusa de viscose com toque de seda e caimento fluido. Sem transparência sob luz direta — testada, porque é onde a maioria das blusas claras falha.</p>', 'Deco Store', 'Blouse', '2026-08-05T00:00:00Z', 'BRL', 120),
('gid://catalog/Product/9021', 'flannel-overshirt', 'Flannel Overshirt - Blue', 'Sobrecamisa de flanela escovada, mais pesada que camisa e mais leve que jaqueta. Ocupa aquela faixa de temperatura em que casaco é demais e camiseta é pouco.', '<p>Sobrecamisa de flanela escovada, mais pesada que camisa e mais leve que jaqueta. Ocupa aquela faixa de temperatura em que casaco é demais e camiseta é pouco.</p>', 'Deco Store', 'Shirt', '2026-08-05T00:00:00Z', 'BRL', 121),
('gid://catalog/Product/9022', 'classic-bomber-jacket', 'Classic Bomber Jacket - Brown', 'Bomber de gola, punho e barra canelados, com forro leve e bolso interno com zíper. O corte para na cintura, então funciona bem sobre moletom sem criar volume embaixo.', '<p>Bomber de gola, punho e barra canelados, com forro leve e bolso interno com zíper. O corte para na cintura, então funciona bem sobre moletom sem criar volume embaixo.</p>', 'Deco Store', 'Bomber Jacket', '2026-08-05T00:00:00Z', 'BRL', 122),
('gid://catalog/Product/9023', 'faux-leather-biker', 'Faux Leather Biker - Black', 'Jaqueta biker em couro sintético de superfície fosca, com zíper diagonal e lapela assimétrica. O forro é acetinado, o que faz vestir e tirar sem prender na manga da blusa.', '<p>Jaqueta biker em couro sintético de superfície fosca, com zíper diagonal e lapela assimétrica. O forro é acetinado, o que faz vestir e tirar sem prender na manga da blusa.</p>', 'Deco Store', 'Leather Jacket', '2026-08-05T00:00:00Z', 'BRL', 123),
('gid://catalog/Product/9024', 'denim-trucker-jacket', 'Denim Trucker Jacket - Indigo', 'Jaqueta jeans de corte trucker, com bolsos no peito e ajuste lateral por botão. Denim de 12oz sem elastano, que amolda ao corpo com o uso em vez de já vir amaciado.', '<p>Jaqueta jeans de corte trucker, com bolsos no peito e ajuste lateral por botão. Denim de 12oz sem elastano, que amolda ao corpo com o uso em vez de já vir amaciado.</p>', 'Deco Store', 'Denim Jacket', '2026-08-05T00:00:00Z', 'BRL', 124),
('gid://catalog/Product/9025', 'hooded-rain-shell', 'Hooded Rain Shell - Olive', 'Corta-vento impermeável com costuras seladas e capuz ajustável. Leve o bastante para dobrar dentro da mochila, o que é a diferença entre levar sempre e nunca levar.', '<p>Corta-vento impermeável com costuras seladas e capuz ajustável. Leve o bastante para dobrar dentro da mochila, o que é a diferença entre levar sempre e nunca levar.</p>', 'Deco Store', 'Rain Jacket', '2026-08-05T00:00:00Z', 'BRL', 125),
('gid://catalog/Product/9026', 'tailored-blazer', 'Tailored Blazer - Black', 'Blazer de dois botões com ombro leve e forro parcial. Estruturado o suficiente para ocasião formal, macio o suficiente para usar por cima de camiseta num sábado.', '<p>Blazer de dois botões com ombro leve e forro parcial. Estruturado o suficiente para ocasião formal, macio o suficiente para usar por cima de camiseta num sábado.</p>', 'Deco Store', 'Blazer', '2026-08-05T00:00:00Z', 'BRL', 126),
('gid://catalog/Product/9027', 'quilted-liner-jacket', 'Quilted Liner Jacket - Brown', 'Jaqueta matelassê fina, feita para ser a camada do meio. Cabe por baixo de casaco maior sem apertar e sai sozinha em dia ameno.', '<p>Jaqueta matelassê fina, feita para ser a camada do meio. Cabe por baixo de casaco maior sem apertar e sai sozinha em dia ameno.</p>', 'Deco Store', 'Jacket', '2026-08-05T00:00:00Z', 'BRL', 127),
('gid://catalog/Product/9028', 'straight-leg-jeans', 'Straight Leg Jeans - Light Blue', 'Jeans de perna reta em denim rígido de 13oz, cintura média. Sem elastano: veste firme no primeiro dia e vai cedendo ao corpo em vez de ceder no joelho.', '<p>Jeans de perna reta em denim rígido de 13oz, cintura média. Sem elastano: veste firme no primeiro dia e vai cedendo ao corpo em vez de ceder no joelho.</p>', 'Deco Store', 'Jeans', '2026-08-05T00:00:00Z', 'BRL', 128),
('gid://catalog/Product/9029', 'relaxed-mom-jeans', 'Relaxed Mom Jeans - Blue', 'Cintura alta, quadril folgado e barra virada. A modelagem mom clássica, com denim de toque seco que sustenta a forma em vez de amassar atrás do joelho.', '<p>Cintura alta, quadril folgado e barra virada. A modelagem mom clássica, com denim de toque seco que sustenta a forma em vez de amassar atrás do joelho.</p>', 'Deco Store', 'Jeans', '2026-08-05T00:00:00Z', 'BRL', 129),
('gid://catalog/Product/9030', 'slim-stretch-jeans', 'Slim Stretch Jeans - Light Blue', 'Jeans slim com 2% de elastano, o mínimo para dar mobilidade sem virar legging. Bolso traseiro fundo, que é onde jeans slim costuma decepcionar.', '<p>Jeans slim com 2% de elastano, o mínimo para dar mobilidade sem virar legging. Bolso traseiro fundo, que é onde jeans slim costuma decepcionar.</p>', 'Deco Store', 'Jeans', '2026-08-05T00:00:00Z', 'BRL', 130),
('gid://catalog/Product/9031', 'cargo-jogger-pants', 'Cargo Jogger Pants - Pink', 'Jogger com bolsos cargo laterais de fole e punho elástico na barra. Tecido de sarja leve com toque seco — não é moletom, então serve fora de casa sem parecer pijama.', '<p>Jogger com bolsos cargo laterais de fole e punho elástico na barra. Tecido de sarja leve com toque seco — não é moletom, então serve fora de casa sem parecer pijama.</p>', 'Deco Store', 'Joggers', '2026-08-05T00:00:00Z', 'BRL', 131),
